import { DURATION, CHAPTERS, yearsOfExperience } from './reel/timeline.js';
import { decodePhone, phoneImage } from './phone.js';

const root = document.documentElement;
const body = document.body;
root.classList.add('js');
const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
const $ = (sel, el = document) => el.querySelector(sel);
const $$ = (sel, el = document) => [...el.querySelectorAll(sel)];
const clamp = (x, a = 0, b = 1) => Math.min(b, Math.max(a, x));
const mod = (x, m) => ((x % m) + m) % m;
const POSTER_T = 14.9;

// ── Facts that should never go stale ───────────────────────────────────────
const years = yearsOfExperience();
$$('[data-years]').forEach((el) => (el.textContent = years));
$$('[data-year]').forEach((el) => (el.textContent = new Date().getFullYear()));

// ── Reveal on scroll: a short fade and lift ────────────────────────────────
$$('[data-reveal]').forEach((el) => {
  const siblings = [...el.parentElement.children].filter((c) => c.hasAttribute('data-reveal'));
  el.style.setProperty('--i', Math.min(siblings.indexOf(el), 3));
});
const revealer = new IntersectionObserver(
  (entries) =>
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      entry.target.classList.add('is-in');
      revealer.unobserve(entry.target);
    }),
  { rootMargin: '0px 0px -6% 0px', threshold: 0.08 },
);
$$('[data-reveal]').forEach((el) => revealer.observe(el));

// ── Navigation: active section, mobile menu ────────────────────────────────
const nav = $('#nav');
const links = new Map($$('.nav-links a').map((a) => [a.hash.slice(1), a]));
const navPill = $('.nav-pill');
const movePill = (a) => {
  if (!a) return navPill.style.setProperty('--po', 0);
  navPill.style.setProperty('--px', `${a.offsetLeft - 12}px`);
  navPill.style.setProperty('--pw', `${a.offsetWidth + 24}px`);
  navPill.style.setProperty('--po', 1);
};
const setActive = (id) => {
  links.forEach((a) => a.removeAttribute('aria-current'));
  const a = id && links.get(id);
  a?.setAttribute('aria-current', 'true');
  movePill(a);
};
const spy = new IntersectionObserver(
  (entries) =>
    entries.forEach((entry) => {
      if (entry.isIntersecting) setActive(entry.target.id);
    }),
  { rootMargin: '-45% 0px -50% 0px' },
);
$$('main section[id]').forEach((s) => spy.observe(s));
const navToggle = $('#navToggle');
const setMenu = (open) => {
  body.classList.toggle('nav-open', open);
  navToggle.setAttribute('aria-expanded', String(open));
  navToggle.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
};
navToggle.addEventListener('click', () => setMenu(!body.classList.contains('nav-open')));
$$('.nav-links a').forEach((a) => a.addEventListener('click', () => setMenu(false)));

// ── Liquid Glass lens (Chromium renders SVG filters in backdrop-filter) ────
// A capsule-shaped edge map: pixels near the rim are displaced along the normal.
if (navigator.userAgentData?.brands?.some((b) => /Chromium/.test(b.brand))) {
  const W = 256;
  const H = 96;
  const R = H / 2;
  const band = 20;
  const c = document.createElement('canvas');
  c.width = W;
  c.height = H;
  const g = c.getContext('2d');
  const img = g.createImageData(W, H);
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const px = x + 0.5 - W / 2;
      const py = y + 0.5 - H / 2;
      const qx = Math.max(Math.abs(px) - (W / 2 - R), 0);
      const qy = Math.abs(py);
      const len = Math.hypot(qx, qy);
      const m = Math.max(0, 1 - Math.min(1, (R - len) / band)) ** 2;
      const nx = len > 0 ? (qx / len) * Math.sign(px) : 0;
      const ny = len > 0 ? (qy / len) * Math.sign(py) : 0;
      const o = (y * W + x) * 4;
      img.data[o] = 128 + 127 * nx * m;
      img.data[o + 1] = 128 + 127 * ny * m;
      img.data[o + 2] = 128;
      img.data[o + 3] = 255;
    }
  }
  g.putImageData(img, 0, 0);
  $('#lgMap')?.setAttribute('href', c.toDataURL());
  root.classList.add('lens');
}

// ── 3D and glass interactions ──────────────────────────────────────────────
const finePointer = matchMedia('(hover: hover) and (pointer: fine)').matches;
if (finePointer && !reduceMotion) {
  // Cards lean toward the pointer and catch the light.
  $$('.tilt').forEach((el) => {
    const max = Number(el.dataset.tilt || 5);
    let raf = 0;
    el.addEventListener('pointermove', (e) => {
      const r = el.getBoundingClientRect();
      const px = (e.clientX - r.left) / r.width;
      const py = (e.clientY - r.top) / r.height;
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        el.classList.add('is-tilting');
        el.style.setProperty('--ry', `${((px - 0.5) * 2 * max).toFixed(2)}deg`);
        el.style.setProperty('--rx', `${((0.5 - py) * 2 * max).toFixed(2)}deg`);
        el.style.setProperty('--gx', `${(px * 100).toFixed(1)}%`);
        el.style.setProperty('--gy', `${(py * 100).toFixed(1)}%`);
        el.style.setProperty('--glare', 1);
      });
    });
    el.addEventListener('pointerleave', () => {
      cancelAnimationFrame(raf);
      el.classList.remove('is-tilting');
      el.style.setProperty('--rx', '0deg');
      el.style.setProperty('--ry', '0deg');
      el.style.setProperty('--glare', 0);
    });
  });
  // Glass controls: the specular highlight tracks the pointer.
  $$('.btn, .pill-btn, .nav-inner, .player, .mini, .cinema-bar').forEach((el) => {
    el.addEventListener('pointermove', (e) => {
      const r = el.getBoundingClientRect();
      el.style.setProperty('--lx', `${(((e.clientX - r.left) / r.width) * 100).toFixed(1)}%`);
      el.style.setProperty('--ly', `${(((e.clientY - r.top) / r.height) * 100 - 30).toFixed(1)}%`);
    });
    el.addEventListener('pointerleave', () => {
      el.style.removeProperty('--lx');
      el.style.removeProperty('--ly');
    });
  });
}

// Skills: a segmented control filters by where each skill was used.
{
  const seg = $('.segmented');
  const thumb = $('.segmented-thumb', seg);
  const buttons = $$('button', seg);
  const card = $('#skills .skills');
  const chips = $$('.chip', card);
  const count = $('#filterCount');
  const place = (btn) => {
    thumb.style.setProperty('--sx', `${btn.offsetLeft}px`);
    thumb.style.setProperty('--sw', `${btn.offsetWidth}px`);
    thumb.style.setProperty('--sy', `${btn.offsetTop}px`);
    thumb.style.setProperty('--sh', `${btn.offsetHeight}px`);
  };
  const select = (btn, focus = false) => {
    buttons.forEach((b) => {
      const on = b === btn;
      b.setAttribute('aria-checked', String(on));
      b.tabIndex = on ? 0 : -1;
    });
    if (focus) btn.focus();
    place(btn);
    const f = btn.dataset.filter;
    if (f === 'all') {
      card.classList.remove('filtering');
      chips.forEach((c) => c.classList.remove('is-match'));
      count.textContent = `${chips.length} skills`;
      return;
    }
    let n = 0;
    chips.forEach((c) => {
      const used = (c.dataset.used || '').split(' · ');
      const hit = f === 'intern' ? used.some((u) => u.includes('(intern)')) : used.includes(f);
      c.classList.toggle('is-match', hit);
      n += hit ? 1 : 0;
    });
    card.classList.add('filtering');
    count.textContent = `${n} used ${f === 'intern' ? 'in internships' : `at ${btn.textContent}`}`;
  };
  buttons.forEach((b, i) => {
    b.addEventListener('click', () => select(b));
    b.addEventListener('keydown', (e) => {
      const d = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 }[e.key];
      if (!d) return;
      e.preventDefault();
      select(buttons[(i + d + buttons.length) % buttons.length], true);
    });
  });
  const init = () => select(buttons.find((b) => b.getAttribute('aria-checked') === 'true') || buttons[0]);
  init();
  document.fonts?.ready.then(init);
  addEventListener('resize', () => place(buttons.find((b) => b.getAttribute('aria-checked') === 'true')));
}

// "How it's made" opens the film notes where they live.
$$('[data-open-notes]').forEach((a) =>
  a.addEventListener('click', () => {
    const notes = $('#film-notes');
    if (notes) notes.open = true;
  }),
);

// ── Small interactions ─────────────────────────────────────────────────────
const toast = $('#toast');
let toastTimer;
const say = (msg) => {
  toast.textContent = msg;
  toast.classList.add('is-on');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove('is-on'), 1800);
};
$$('[data-copy]').forEach((btn) =>
  btn.addEventListener('click', async () => {
    try {
      await navigator.clipboard.writeText(btn.dataset.copy);
      say('Email copied');
    } catch {
      say(btn.dataset.copy);
    }
  }),
);

// ── Phone: never in the markup. Decoded and drawn as an image on request ───
$('#revealPhone')?.addEventListener('click', (e) => {
  const number = decodePhone();
  const slot = $('#phoneSlot');
  const cs = getComputedStyle(slot);
  slot.replaceChildren(phoneImage(number, { size: parseFloat(cs.fontSize) || 19, color: cs.color, weight: cs.fontWeight }));
  const actions = document.createElement('span');
  actions.className = 'phone-actions';
  const copy = document.createElement('button');
  copy.type = 'button';
  copy.className = 'pill-btn';
  copy.textContent = 'Copy';
  copy.addEventListener('click', async () => {
    try {
      await navigator.clipboard.writeText(number);
      say('Number copied');
    } catch {
      say('Copy not available');
    }
  });
  actions.append(copy);
  if (matchMedia('(pointer: coarse)').matches) {
    const call = document.createElement('button');
    call.type = 'button';
    call.className = 'pill-btn';
    call.textContent = 'Call';
    call.addEventListener('click', () => (location.href = `tel:${number.replace(/\s+/g, '')}`));
    actions.append(call);
  }
  e.currentTarget.replaceWith(actions);
});

// ── The soundtrack ─────────────────────────────────────────────────────────
// Pre-rendered AAC (tiny, decodes instantly); falls back to synthesising it in the browser.
// It loops natively, and while it plays the picture follows the audio clock — so the two
// can never drift, and nothing restarts mid-play.
const audio = (() => {
  let ctx = null;
  let gain = null;
  let buffer = null;
  let loading = null;
  let source = null;
  let startCtx = 0;
  let startOffset = 0;
  let lastClock = -1;
  let lastClockAt = 0;
  const fetchTrack = async () => {
    try {
      const res = await fetch('media/soundtrack.m4a');
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      // An offline context decodes without tripping autoplay rules.
      return await new OfflineAudioContext(2, 1, 48000).decodeAudioData(await res.arrayBuffer());
    } catch {
      const { renderSoundtrack } = await import('./reel/audio.js');
      return renderSoundtrack({ sampleRate: 48000 });
    }
  };
  return {
    load: () => (loading ||= fetchTrack().then((b) => (buffer = b))),
    get ready() {
      return !!buffer;
    },
    // Must run synchronously inside the click that asked for sound.
    unlock() {
      if (!ctx) {
        const AC = window.AudioContext || window.webkitAudioContext;
        ctx = new AC({ latencyHint: 'playback' });
        gain = ctx.createGain();
        gain.connect(ctx.destination);
      }
      if (ctx.state !== 'running') ctx.resume().catch(() => {});
    },
    play(from) {
      this.stop();
      if (!ctx || !buffer) return;
      source = ctx.createBufferSource();
      source.buffer = buffer;
      source.loop = true;
      // AAC adds a few ms of padding; loop on exactly the film's length so they never drift.
      source.loopStart = 0;
      source.loopEnd = Math.min(buffer.duration, DURATION);
      source.connect(gain);
      startCtx = ctx.currentTime + 0.04;
      startOffset = mod(from, DURATION);
      source.start(startCtx, startOffset);
      lastClock = -1;
    },
    stop() {
      if (!source) return;
      try {
        source.stop();
      } catch {}
      source.disconnect();
      source = null;
    },
    volume(v, fast = false) {
      if (gain) gain.gain.setTargetAtTime(v, ctx.currentTime, fast ? 0.02 : 0.25);
    },
    // Film time as heard right now, or null when the audio clock isn't advancing.
    time(now) {
      if (!source || ctx.state !== 'running') return null;
      const clock = ctx.currentTime;
      if (clock !== lastClock) {
        lastClock = clock;
        lastClockAt = now;
      } else if (now - lastClockAt > 300) return null;
      let heard;
      const stamp = ctx.getOutputTimestamp?.();
      if (stamp && stamp.performanceTime > 0 && stamp.contextTime > 0) heard = stamp.contextTime + (now - stamp.performanceTime) / 1000;
      else heard = clock - clamp(ctx.outputLatency || ctx.baseLatency || 0, 0, 0.5);
      if (heard < startCtx) return startOffset;
      return mod(startOffset + heard - startCtx, DURATION);
    },
  };
})();

// ── The film, as the page's backdrop ───────────────────────────────────────
const backdrop = $('.backdrop');
const canvas = $('#reel');
const hero = $('#top');
const heroInner = $('.hero-inner');
const mini = $('#mini');
const seek = $('#seek');
const timecode = $('#timecode');
const ringFill = $('#ringFill');
const segmentsEl = $('#segments');
const chaptersEl = $('#chapters');
const roles = $('#roles');
const roleItems = $$('.role', roles);
const playBtns = [$('#play'), $('#miniPlay'), $('#cinemaPlay')];
const soundBtns = $$('[data-sound]');

const chapterSpans = CHAPTERS.map((c, i) => ({ ...c, end: CHAPTERS[i + 1]?.start ?? DURATION }));
chapterSpans.forEach((c) => {
  const len = (c.end - c.start).toFixed(2);
  const seg = document.createElement('span');
  seg.className = 'seg';
  seg.style.setProperty('--len', len);
  seg.append(document.createElement('i'));
  segmentsEl.append(seg);
  const li = document.createElement('li');
  li.style.setProperty('--len', len);
  const b = document.createElement('button');
  b.type = 'button';
  b.textContent = c.label;
  b.addEventListener('click', () => seekTo(c.start + 0.001, true));
  li.append(b);
  chaptersEl.append(li);
});
const segEls = $$('.seg i', segmentsEl);
const chapterEls = $$('li', chaptersEl);
const fmt = (s) => `0:${String(Math.floor(s)).padStart(2, '0')}`;
seek.max = String(DURATION);
timecode.lastElementChild.textContent = `/ ${fmt(DURATION)}`;

let reel = null;
let t = 0;
let playing = false;
let userPaused = reduceMotion;
let soundOn = false;
let dragging = false;
let dirty = true;
let quality = 1;
let ambient = 0;
let frameSkip = false;
let last = performance.now();
const renderCost = [];
const cinemaOn = () => body.classList.contains('cinema');

const setPlaying = (next) => {
  playing = next;
  body.classList.toggle('is-paused', !next);
  playBtns.forEach((b) => b.setAttribute('aria-label', next ? 'Pause the film' : 'Play the film'));
  if (next && soundOn && audio.ready) audio.play(t);
  if (!next) audio.stop();
  last = performance.now();
};

const seekTo = (time, commit) => {
  t = clamp(time, 0, DURATION - 0.001);
  dirty = true;
  if (commit && playing && soundOn && audio.ready) audio.play(t);
};

const targetVolume = () => (cinemaOn() ? 1 : 1 - 0.5 * ambient);
const updateSoundUi = () => {
  body.classList.toggle('has-sound', soundOn);
  const loading = body.classList.contains('sound-loading');
  soundBtns.forEach((b) => {
    b.setAttribute('aria-pressed', String(soundOn));
    b.setAttribute('aria-label', soundOn ? 'Turn sound off' : 'Turn sound on');
    const label = $('.sound-label', b);
    if (label) label.textContent = loading ? 'Loading…' : soundOn ? 'Sound on' : 'Sound off';
  });
};
const setSound = async (on) => {
  soundOn = on;
  if (!on) {
    audio.stop();
    updateSoundUi();
    return;
  }
  audio.unlock();
  if (!audio.ready) {
    body.classList.add('sound-loading');
    updateSoundUi();
    try {
      await audio.load();
    } catch (error) {
      console.warn('Sound unavailable', error);
      soundOn = false;
      say('Sound is not available in this browser');
    }
    body.classList.remove('sound-loading');
  }
  updateSoundUi();
  if (!soundOn) return;
  audio.volume(targetVolume(), true);
  if (!playing) {
    userPaused = false;
    setPlaying(true);
  } else audio.play(t);
};

// Where the graph may sit on the page: below the nav, above the hero copy.
const heroPlayer = $('#player');
const pageSafe = () => {
  const H = innerHeight;
  const inHero = (el) => el.getBoundingClientRect().top + scrollY - hero.offsetTop;
  let copyTop = inHero(heroInner);
  // On phones the film controls sit above the copy: keep the film (and its name tag) clear of them.
  const playerTop = inHero(heroPlayer) - 10;
  if (heroPlayer.offsetHeight && playerTop < copyTop) copyTop = playerTop;
  return {
    top: (nav.getBoundingClientRect().bottom + 16) / H,
    bottom: clamp((H - copyTop) / H + 0.01, 0.16, 0.66),
    left: 0.025,
    right: 0.025,
  };
};

// Canvas resolution follows the viewport; lower when the film is only a soft backdrop.
const resize = () => {
  if (!reel) return;
  const r = canvas.getBoundingClientRect();
  const big = r.width * r.height > 1.1e6;
  const dpr = Math.min(devicePixelRatio || 1, big ? 1.5 : 2) * quality * (ambient > 0.9 && !cinemaOn() ? 0.6 : 1);
  const w = Math.max(320, Math.round(r.width * dpr));
  const h = Math.max(320, Math.round(r.height * dpr));
  if (Math.abs(canvas.width - w) > 2 || Math.abs(canvas.height - h) > 2) {
    reel.resize(w, h);
    dirty = true;
  }
  if (!cinemaOn()) reel.setSafe(pageSafe());
};

const scrubEl = $('.scrub');
const updateUi = () => {
  ringFill.style.setProperty('--p', (t / DURATION).toFixed(4));
  if (!cinemaOn()) return;
  scrubEl.style.setProperty('--sp', (t / DURATION).toFixed(4));
  timecode.firstChild.textContent = `${fmt(t)} `;
  if (!dragging) seek.value = t.toFixed(2);
  chapterSpans.forEach((c, i) => {
    segEls[i].style.setProperty('--p', clamp((t - c.start) / (c.end - c.start)).toFixed(4));
    chapterEls[i].classList.toggle('is-current', t >= c.start && t < c.end);
  });
};

let aimX = 0;
let aimY = 0;
let lookX = 0;
let lookY = 0;
if (finePointer && !reduceMotion) {
  addEventListener(
    'pointermove',
    (e) => {
      aimX = (e.clientX / innerWidth) * 2 - 1;
      aimY = (e.clientY / innerHeight) * 2 - 1;
    },
    { passive: true },
  );
}
const loop = (now) => {
  requestAnimationFrame(loop);
  const dt = Math.min(0.1, (now - last) / 1000);
  last = now;
  if (!reel) return;
  if (reel.setPointer) {
    const tx = cinemaOn() ? 0 : aimX;
    const ty = cinemaOn() ? 0 : aimY;
    const k = 1 - Math.exp(-dt * 3.5);
    const nx = lookX + (tx - lookX) * k;
    const ny = lookY + (ty - lookY) * k;
    if (Math.abs(nx - lookX) + Math.abs(ny - lookY) > 1e-4) {
      lookX = nx;
      lookY = ny;
      reel.setPointer(lookX, lookY);
      dirty = true;
    }
  }
  if (playing && !dragging) {
    const heard = soundOn ? audio.time(now) : null;
    t = heard ?? mod(t + dt, DURATION);
    dirty = true;
  }
  if (!dirty) return;
  // Behind content the backdrop runs at 30 fps — invisible through the scrim.
  frameSkip = !frameSkip;
  if (ambient > 0.9 && playing && frameSkip && !cinemaOn()) return;
  dirty = false;
  const s = performance.now();
  reel.render(t);
  updateUi();
  renderCost.push(performance.now() - s);
  if (renderCost.length > 45) {
    const avg = renderCost.reduce((a, b) => a + b, 0) / renderCost.length;
    renderCost.length = 0;
    if (avg > 11 && quality > 0.5) {
      quality = Math.max(0.5, quality * 0.8);
      resize();
    }
  }
};

// ── Scroll: the film softens into a backdrop as the CV slides over it ──────
let lastY = scrollY;
const onScroll = () => {
  const y = scrollY;
  const max = root.scrollHeight - innerHeight;
  root.style.setProperty('--scroll', max > 0 ? (y / max).toFixed(4) : 0);
  const next = cinemaOn() ? 0 : clamp(y / (innerHeight * 0.7));
  if (Math.abs(next - ambient) > 0.002) {
    const crossed = next > 0.9 !== ambient > 0.9;
    ambient = next;
    root.style.setProperty('--dim', ambient.toFixed(3));
    reel?.setAmbient(ambient);
    if (soundOn) audio.volume(targetVolume());
    if (crossed) resize();
    dirty = true;
  }
  body.classList.toggle('scrolled', y > innerHeight * 0.25);
  if (y > lastY + 6 && y > innerHeight * 0.6) body.classList.add('nav-compact');
  else if (y < lastY - 6 || y < innerHeight * 0.6) body.classList.remove('nav-compact');
  lastY = y;
  if (y < innerHeight * 0.5) setActive(null);
  const nearEnd = y > max - innerHeight * 0.5;
  mini.classList.toggle('is-on', y > innerHeight * 0.8 && !nearEnd && !cinemaOn());
  // Experience rail.
  const line = innerHeight * 0.55;
  const r = roles.getBoundingClientRect();
  roles.style.setProperty('--rail', clamp((line - r.top) / r.height).toFixed(4));
  roleItems.forEach((item) => item.classList.toggle('is-active', item.getBoundingClientRect().top + 40 < line));
};
addEventListener('scroll', onScroll, { passive: true });
addEventListener('resize', () => {
  onScroll();
  resize();
});

// ── Controls ───────────────────────────────────────────────────────────────
const togglePlay = () => {
  userPaused = playing;
  setPlaying(!playing);
};
let idleTimer;
const wake = () => {
  body.classList.remove('idle');
  clearTimeout(idleTimer);
  if (cinemaOn()) idleTimer = setTimeout(() => body.classList.add('idle'), 2600);
};
const setCinema = (on) => {
  body.classList.toggle('cinema', on);
  setMenu(false);
  if (on) scrollTo({ top: 0, behavior: 'instant' });
  // Fullscreen is the film as cut: name, stage captions and the end card.
  reel?.setTitles(on);
  reel?.setSafe(on ? null : pageSafe());
  if (soundOn) audio.volume(targetVolume(), true);
  wake();
  onScroll();
  dirty = true;
  requestAnimationFrame(resize);
};
const enterCinema = () => {
  const req = root.requestFullscreen || root.webkitRequestFullscreen;
  req?.call(root)?.catch?.(() => {});
  setCinema(true);
};
const exitCinema = () => {
  if (document.fullscreenElement || document.webkitFullscreenElement) (document.exitFullscreen || document.webkitExitFullscreen)?.call(document)?.catch?.(() => {});
  setCinema(false);
};
const toggleCinema = () => (cinemaOn() ? exitCinema() : enterCinema());
const onFullscreenChange = () => {
  if (!(document.fullscreenElement || document.webkitFullscreenElement) && cinemaOn()) setCinema(false);
};
document.addEventListener('fullscreenchange', onFullscreenChange);
document.addEventListener('webkitfullscreenchange', onFullscreenChange);
addEventListener('pointermove', wake, { passive: true });

playBtns.forEach((b) => b.addEventListener('click', togglePlay));
soundBtns.forEach((b) => b.addEventListener('click', () => setSound(!soundOn)));
$('#watchFilm').addEventListener('click', () => {
  seekTo(0, false);
  enterCinema();
  userPaused = false;
  if (!soundOn) setSound(true);
  else if (!playing) setPlaying(true);
  else audio.play(0);
});
$('#hit').addEventListener('click', togglePlay);
$('#hit').addEventListener('dblclick', toggleCinema);
$('#cinema').addEventListener('click', toggleCinema);
$('#exitCinema').addEventListener('click', exitCinema);
seek.addEventListener('input', () => {
  dragging = true;
  scrubEl.classList.add('dragging');
  seekTo(Number(seek.value), false);
  updateUi();
});
seek.addEventListener('change', () => {
  dragging = false;
  scrubEl.classList.remove('dragging');
  seekTo(Number(seek.value), true);
});
seek.addEventListener('pointerdown', () => scrubEl.classList.add('dragging'));
addEventListener('pointerup', () => scrubEl.classList.remove('dragging'));
// K / M / F / ← → shortcuts (never while typing).
addEventListener('keydown', (e) => {
  if (e.metaKey || e.ctrlKey || e.altKey || /input|textarea|select/i.test(e.target.tagName)) return;
  const key = e.key.toLowerCase();
  if (key === 'k') togglePlay();
  else if (key === 'm') setSound(!soundOn);
  else if (key === 'f') toggleCinema();
  else if (key === 'escape' && cinemaOn()) exitCinema();
  else if (key === 'escape' && body.classList.contains('nav-open')) setMenu(false);
  else if ((key === 'arrowleft' || key === 'arrowright') && cinemaOn()) seekTo(t + (key === 'arrowleft' ? -2 : 2), true);
  else return;
  e.preventDefault();
  wake();
});

document.addEventListener('visibilitychange', () => {
  const shouldPlay = !document.hidden && !userPaused;
  if (shouldPlay !== playing) setPlaying(shouldPlay);
});

// The film is 3D (WebGL2); without it, the 2D canvas version takes over.
const coarse = matchMedia('(pointer: coarse)').matches;
const makeReel = async (opts) => {
  const gl = document.createElement('canvas').getContext('webgl2');
  if (gl) {
    try {
      const { createReel } = await import('./reel/reel3d.js');
      return await createReel(canvas, opts);
    } catch (error) {
      console.warn('3D film unavailable; using the 2D version.', error);
    }
  }
  const { createReel } = await import('./reel/reel.js');
  return createReel(canvas, opts);
};

new ResizeObserver(resize).observe(canvas);
onScroll();
updateSoundUi();

(async () => {
  try {
    reel = await makeReel({ format: 'auto', titles: false, safe: pageSafe(), lite: coarse });
    resize();
    onScroll();
    reel.setAmbient(ambient);
    if (reduceMotion) t = POSTER_T;
    reel.render(t);
    updateUi();
    backdrop.classList.add('is-ready');
    setPlaying(!userPaused && !document.hidden);
    requestAnimationFrame(loop);
    // Fetch the soundtrack in the background so "Sound on" is instant.
    const idle = window.requestIdleCallback ? (fn) => requestIdleCallback(fn, { timeout: 3000 }) : (fn) => setTimeout(fn, 1);
    setTimeout(() => idle(() => audio.load().catch(() => {})), 1500);
  } catch (error) {
    console.error('Film failed to start', error);
  }
})();
